package io.github.fengsangzbg.phsradio.mobile;
import org.json.*;
import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.zip.DeflaterOutputStream;
public final class MobileRegressionTest {
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    public static void main(String[] args)throws Exception{
        LrcTimeline lrc=LrcTimeline.parse("\uFEFF[ti:Test]\n[offset:100]\n[00:01.20][00:03.200]第一句\n[00:01.200]translation\n[00:05]末尾");check(lrc.lines.size()==3,"timestamps merged, metadata excluded");check(lrc.lines.get(0).time==1100,"LRC fraction and offset");check(lrc.lines.get(0).text.contains("translation"),"translation retained");check(lrc.at(1099)==-1&&lrc.at(1100)==0&&lrc.at(5000)==2,"timeline seek boundaries");
        LrcTimeline plain=LrcTimeline.parse("[ti:Title]\nNo timestamp lyrics\n第二句");check(plain.lines.isEmpty()&&plain.plain.contains("第二句"),"plain lyrics are displayed, not called missing");
        String krc="[1000,2000]<0,1000,0>第一<1000,1000,0>句";check(LrcTimeline.parse(krc).lines.get(0).text.equals("第一句"),"KRC word stamps stripped");ByteArrayOutputStream compressed=new ByteArrayOutputStream();try(DeflaterOutputStream deflater=new DeflaterOutputStream(compressed)){deflater.write(krc.getBytes(StandardCharsets.UTF_8));}byte[] packed=compressed.toByteArray(),encoded=new byte[packed.length+4];System.arraycopy(new byte[]{'k','r','c','1'},0,encoded,0,4);int[] key={64,71,97,119,94,50,116,71,81,54,49,45,206,210,110,105};for(int i=0;i<packed.length;i++)encoded[i+4]=(byte)(packed[i]^key[i%16]);check(LyricCodec.decode(Base64.getEncoder().encodeToString(encoded)).equals(krc),"KRC compressed content decode");
        JSONObject audio=SongFields.parse(new JSONObject().put("song_info",new JSONObject().put("mixsongid",12345).put("songname","Audio-only metadata").put("sizable_cover","//img.test/{size}/a.jpg")),"kugou");check(audio.getString("id").equals("audio:12345")&&!audio.getBoolean("unavailable"),"audio-id-only track remains playable");check(audio.getString("hash").isEmpty(),"audio id is not sent as a file hash");check(audio.getString("cover").equals("https://img.test/1000/a.jpg"),"protocol-relative cover and original size");
        JSONObject absent=SongFields.parse(new JSONObject().put("name","Missing id"),"kugou");check(absent.getBoolean("unavailable")&&absent.getString("title").equals("Missing id"),"bad row retained without aborting playlist");JSONObject nested=SongFields.parse(new JSONObject().put("base",new JSONObject().put("FileHash","abcdef").put("FileName","Nested")),"kugou");check(nested.getString("id").equals("abcdef"),"nested base hash");
        String cookie=NeteaseAuth.cookies("NMTID=device",new JSONObject().put("_cookie","MUSIC_U=abc==; Path=/").put("data",new JSONObject().put("cookie","__csrf=csrf")));check(NeteaseAuth.authorized(cookie)&&cookie.contains("NMTID=device")&&!cookie.contains("Path="),"QR cookie merge, equals preserved, attributes excluded");check(!NeteaseAuth.authorized("MUSIC_U="),"empty auth cookie rejected");check(NeteaseAuth.code(new JSONObject().put("code",200).put("data",new JSONObject().put("code",802)))==802,"nested scan status");
        System.out.println("PASS: lyric time/offset/plain/KRC cases, nested and audio-only identifiers, cover normalization, QR cookie and state handling");
        if(args.length>0&&args[0].equals("--live")){
            String device=UUID.randomUUID().toString().replace("-","");JSONObject created=NeteaseTransport.request("/api/login/qrcode/unikey",new JSONObject().put("type",3),"",device);JSONObject data=created.optJSONObject("data");String qr=created.optString("unikey",data==null?"":data.optString("unikey"));check(!qr.isEmpty(),"live native Netease QR key");String jar=NeteaseAuth.cookies("",created);JSONObject poll=NeteaseTransport.request("/api/login/qrcode/client/login",new JSONObject().put("key",qr).put("type",3),jar,device);check(NeteaseAuth.code(poll)==801,"fresh native QR is waiting for scan");System.out.println("Live native Netease QR: key accepted, polling status 801 (no account credentials used)");
            android.content.Context context=new android.content.Context();context.getSharedPreferences("accounts",0).edit().putString("mid","00112233445566778899aabbccddeeff").apply();try(OnlineApi api=new OnlineApi(context)){JSONArray songs=api.search("kugou","晴天 周杰伦",0);check(songs.length()>0,"live search");boolean lyrics=false,cover=false;for(int i=0;i<Math.min(3,songs.length());i++){JSONObject track=songs.getJSONObject(i);if(!lyrics){String text=api.lyrics(track);lyrics=!LrcTimeline.parse(text).lines.isEmpty();}if(!cover)cover=api.cover(track).startsWith("https://");if(lyrics&&cover)break;}check(lyrics,"live native Kugou LRC can be fetched and parsed");check(cover,"live native Kugou cover can be resolved");System.out.println("Live native Kugou: timed lyrics parsed and cover URL resolved (content and URLs not logged)");JSONArray lists=api.recommendedPlaylists("kugou");check(lists.length()>0&&!lists.getJSONObject(0).optString("id").isEmpty(),"live public playlist id");int[] valid={0},missing={0};try{api.tracks(lists.getJSONObject(0),()->valid[0]+missing[0]>=100,batch->{for(int n=0;n<batch.length();n++){if(batch.optJSONObject(n).optBoolean("unavailable"))missing[0]++;else valid[0]++;}});}catch(InterruptedIOException expected){}check(valid[0]>0,"live playlist contains usable identifiers");System.out.println("Live public playlist first batch: "+valid[0]+" identified, "+missing[0]+" incomplete");}
        }
    }
}
